use iced::Color;

/// Which of the reference's four looks a value is being asked for.
///
/// The order is the order the generated tables are indexed in, so the
/// discriminant of a variant is its column.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Theme {
    /// The light look (`.light-properties`).
    Light,
    /// The dark look (`.dark-mode`), the one the app opens in by default.
    Dark,
    /// `.oled-mode`: dark's surfaces taken to true black.
    Oled,
    /// `.retro-mode`: dark with a warmer, desaturated palette.
    Retro,
}

impl Theme {
    /// The column this theme's value sits in.
    const fn index(self) -> usize {
        self as usize
    }

    /// Every theme, for a gate that has to visit all of them.
    pub const ALL: &'static [Theme] = &[Theme::Light, Theme::Dark, Theme::Oled, Theme::Retro];
}

