/// The colour a token is in a theme.
///
/// Total by construction: every token is resolved for every theme before
/// this file is written, so there is no `Option` to handle at a call site
/// and no `unwrap` to justify. A token missing from a theme is a
/// generation error, printed by `tools/gen_theme.py --report`.
pub fn ink(theme: Theme, token: Ink) -> Color {
    let [r, g, b, a] = ink_rgba(theme, token);
    Color::from_rgba8(r, g, b, a as f32 / 255.0)
}

/// The same value as `ink`, as the four bytes the CSS declared.
///
/// Separate from `ink` so that a gate can assert a hex value without
/// going through a float, and so that the rounding a float colour
/// introduces never decides whether a gate passes.
pub fn ink_rgba(theme: Theme, token: Ink) -> [u8; 4] {
    match INK_TABLE.binary_search_by_key(&(token as u8), |(key, _)| *key as u8) {
        Ok(found) => INK_TABLE[found].1[theme.index()],
        // Unreachable by construction, and a value rather than a panic
        // because this crate denies `unwrap` outside tests. Transparent
        // black is the one answer that cannot be mistaken for paint.
        Err(_) => [0, 0, 0, 0],
    }
}

/// A length, in logical pixels.
pub fn span(token: Span) -> f32 {
    match SPAN_TABLE.binary_search_by_key(&(token as u8), |(key, _)| *key as u8) {
        Ok(found) => SPAN_TABLE[found].1,
        Err(_) => 0.0,
    }
}

/// A bare number, per theme.
pub fn factor(theme: Theme, token: Factor) -> f32 {
    match FACTOR_TABLE.binary_search_by_key(&(token as u8), |(key, _)| *key as u8) {
        Ok(found) => FACTOR_TABLE[found].1[theme.index()],
        Err(_) => 0.0,
    }
}

/// The four control points of a curve, for a tween to evaluate.
pub fn curve(token: Curve) -> [f32; 4] {
    match CURVE_TABLE.binary_search_by_key(&(token as u8), |(key, _)| *key as u8) {
        Ok(found) => CURVE_TABLE[found].1,
        Err(_) => [0.0, 0.0, 1.0, 1.0],
    }
}

/// A value that is not a scalar, per theme, verbatim.
pub fn raw(theme: Theme, token: Raw) -> &'static str {
    match RAW_TABLE.binary_search_by_key(&(token as u8), |(key, _)| *key as u8) {
        Ok(found) => RAW_TABLE[found].1[theme.index()],
        Err(_) => "",
    }
}

