/// The theme the app opens in, and the one every measurement in
/// `REFERENCE.md` was taken in.
pub const DEFAULT_THEME: Theme = Theme::Dark;

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_table_is_sorted_so_its_lookup_is_valid() {
        // `binary_search_by_key` is only a search if the table is sorted by
        // the same key, which is the one assumption the accessors make.
        for pair in INK_TABLE.windows(2) {
            assert!((pair[0].0 as u8) < (pair[1].0 as u8), "INK_TABLE is out of order");
        }
        for pair in SPAN_TABLE.windows(2) {
            assert!((pair[0].0 as u8) < (pair[1].0 as u8), "SPAN_TABLE is out of order");
        }
        for pair in FACTOR_TABLE.windows(2) {
            assert!((pair[0].0 as u8) < (pair[1].0 as u8), "FACTOR_TABLE is out of order");
        }
        for pair in CURVE_TABLE.windows(2) {
            assert!((pair[0].0 as u8) < (pair[1].0 as u8), "CURVE_TABLE is out of order");
        }
        for pair in RAW_TABLE.windows(2) {
            assert!((pair[0].0 as u8) < (pair[1].0 as u8), "RAW_TABLE is out of order");
        }
    }

    #[test]
    fn the_tables_cover_every_variant() {
        assert_eq!(INK_TABLE.len(), ALL_INK.len());
        assert_eq!(SPAN_TABLE.len(), ALL_SPAN.len());
        assert_eq!(FACTOR_TABLE.len(), ALL_FACTOR.len());
        assert_eq!(CURVE_TABLE.len(), ALL_CURVE.len());
        assert_eq!(RAW_TABLE.len(), ALL_RAW.len());
    }

    #[test]
    fn every_token_resolves_in_every_theme() {
        for theme in Theme::ALL {
            for token in ALL_INK {
                let [_, _, _, alpha] = ink_rgba(*theme, *token);
                // A colour with no value would resolve to transparent black,
                // which is only ever legitimate as an explicit `transparent`.
                let declared_transparent = ["Transparent", "AccentContrast"];
                let name = format!("{:?}", token);
                assert!(
                    alpha != 0 || declared_transparent.contains(&name.as_str()),
                    "{name} has no value in {theme:?}"
                );
            }
            for token in ALL_SPAN {
                assert!(span(*token) > 0.0, "{token:?} has no value");
            }
        }
    }

    #[test]
    fn the_surfaces_are_the_ones_the_reference_paints() {
        // Recorded in REFERENCE.md off the reference's own window: the page is
        // `#16181c` in dark, the chrome above it `#27292e`, and OLED takes the
        // page to true black.
        assert_eq!(ink_rgba(Theme::Dark, Ink::Surface1), [0x16, 0x18, 0x1c, 0xff]);
        assert_eq!(ink_rgba(Theme::Dark, Ink::Surface3), [0x27, 0x29, 0x2e, 0xff]);
        assert_eq!(ink_rgba(Theme::Oled, Ink::Surface1), [0x00, 0x00, 0x00, 0xff]);
        assert_eq!(ink_rgba(Theme::Light, Ink::Surface1), [0xeb, 0xeb, 0xeb, 0xff]);
        assert_eq!(ink_rgba(Theme::Retro, Ink::Surface1), [0x19, 0x19, 0x17, 0xff]);
    }

    #[test]
    fn the_accent_is_followed_through_its_indirection_per_theme() {
        // `--color-brand` is `var(--color-green)`, which is `var(--color-green-600)`
        // in light and `var(--color-green-500)` in dark, and is replaced outright in
        // retro. A generator that read the literal line would answer `var(...)` to
        // all four; this is the assertion that it followed the chain.
        assert_eq!(ink_rgba(Theme::Light, Ink::Brand), [0x00, 0xaf, 0x5c, 0xff]);
        assert_eq!(ink_rgba(Theme::Dark, Ink::Brand), [0x1b, 0xd9, 0x6a, 0xff]);
        assert_eq!(ink_rgba(Theme::Oled, Ink::Brand), [0x1b, 0xd9, 0x6a, 0xff]);
        assert_eq!(ink_rgba(Theme::Retro, Ink::Brand), [0x4d, 0x92, 0x27, 0xff]);
    }

    #[test]
    fn the_hover_factor_moves_the_way_the_reference_says() {
        // Two values, not one: light *darkens* a control under the pointer.
        assert_eq!(factor(Theme::Light, Factor::HoverBrightness), 0.9);
        assert_eq!(factor(Theme::Dark, Factor::HoverBrightness), 1.25);
        assert_eq!(factor(Theme::Retro, Factor::HoverBrightness), 1.25);
    }

    #[test]
    fn the_radii_are_rem_converted_at_the_browsers_own_root() {
        assert_eq!(span(Span::RadiusXs), 4.0);
        assert_eq!(span(Span::RadiusSm), 8.0);
        assert_eq!(span(Span::RadiusMd), 12.0);
        assert_eq!(span(Span::RadiusLg), 16.0);
        assert_eq!(span(Span::RadiusXl), 20.0);
    }

    #[test]
    fn the_reference_easing_is_the_one_it_declares() {
        assert_eq!(curve(Curve::EaseOutExpo), [0.16, 1.0, 0.3, 1.0]);
    }

    #[test]
    fn the_motion_table_is_not_empty_and_names_its_sources() {
        assert!(!MOTION.is_empty());
        for motion in MOTION {
            assert!(motion.millis > 0, "{} has no duration", motion.property);
            // The reference's longest transition is 2s. Every row past this
            // bound written so far was the generator's own unit error, not a
            // slow animation: `--check` compares bytes, so only a bound in the
            // tool catches a wrong number both files agree on.
            assert!(
                motion.millis <= 2000,
                "{} declares {}ms, longer than any transition in the reference",
                motion.property,
                motion.millis
            );
            assert!(motion.source.ends_with(".css") || motion.source.ends_with(".scss")
                || motion.source.ends_with(".vue"));
        }
        assert!(!KEYFRAMES.is_empty());
    }

    #[test]
    fn the_scale_the_markup_is_written_in_is_named() {
        // `p-4` is 16px and `text-sm` is 14px on a 20px line; the shell's
        // layout numbers are these, not chosen.
        assert!(TAILWIND.spacing.contains(&16.0));
        assert!(TAILWIND.font_size.contains(&(14.0, 20.0)));
        assert!(TAILWIND.font_weight.iter().any(|(_, w)| *w == 800));
    }
}
